using System;using System.Drawing;using System.Drawing.Drawing2D;
namespace CuteMouseEffects {
public sealed class CursorShapeInfo{public readonly string Id,Name,Description;public CursorShapeInfo(string i,string n,string d){Id=i;Name=n;Description=d;}}
public static class CursorShapes{
 public static readonly CursorShapeInfo[] All={new CursorShapeInfo("star","\u8776\u7ffc","\u53cc\u7ffc\u679c\u51bb\u8f6e\u5ed3"),new CursorShapeInfo("moon","\u7130\u7fbd","\u706b\u7130\u7eb9\u7406\u957f\u7bad"),new CursorShapeInfo("feather","\u9752\u53f6","\u53f6\u7247\u4e0e\u5ef6\u4f38\u53f6\u8109"),new CursorShapeInfo("drop","\u661f\u7cd6","\u5976\u6cb9\u4e94\u89d2\u661f"),new CursorShapeInfo("petal","\u95ea\u7535","\u53cc\u6298\u7ebf\u95ea\u7535"),new CursorShapeInfo("swirl","\u4e91\u65cb","\u4e09\u5c42\u8f6f\u7ef5\u65cb\u89d2")};
 public static CursorShapeInfo Find(string id){foreach(var s in All)if(string.Equals(s.Id,id,StringComparison.OrdinalIgnoreCase))return s;return All[5];}
 public static void Draw(Graphics g,string id,RectangleF area,Color shadow,Color primary,Color secondary,Color glow,Color core){var s=g.Save();g.SmoothingMode=SmoothingMode.AntiAlias;g.TranslateTransform(area.X,area.Y);g.ScaleTransform(area.Width/48f,area.Height/48f);try{if(id=="hand")Hand(g,shadow,primary,secondary,glow);else if(id=="star")Butterfly(g,shadow,primary,secondary,glow);else if(id=="moon")Flame(g,shadow,primary,secondary,glow);else if(id=="feather")Leaf(g,shadow,primary,secondary,glow,core);else if(id=="drop")CreamStar(g,shadow,primary,secondary,glow);else if(id=="petal")Bolt(g,shadow,primary,secondary,glow);else Swirl(g,shadow,primary,secondary,glow);}finally{g.Restore(s);}}
 static Pen P(Color c,float w){var p=new Pen(c,w);p.LineJoin=LineJoin.Round;p.StartCap=p.EndCap=LineCap.Round;return p;}static void B(GraphicsPath p,float a,float b,float c,float d,float e,float f){PointF s=p.GetLastPoint();p.AddBezier(s.X,s.Y,a,b,c,d,e,f);}static void Paint(Graphics g,GraphicsPath p,Color sh,Color a,Color b,Color rim){RectangleF r=p.GetBounds();using(var z=new LinearGradientBrush(r,a,b,38f))g.FillPath(z,p);using(var q=P(sh,5.4f))g.DrawPath(q,p);using(var q=P(Color.FromArgb(235,rim),2.1f))g.DrawPath(q,p);}static void Hi(Graphics g,Color c,float x,float y,float w,float h){using(var b=new SolidBrush(Color.FromArgb(225,c)))g.FillEllipse(b,x,y,w,h);}
 static void Butterfly(Graphics g,Color sh,Color a,Color b,Color hi){using(var p=new GraphicsPath()){p.StartFigure();p.AddBezier(5,4,13,4,25,10,31,17);B(p,37,13,44,16,43,24);B(p,43,28,40,31,37,32);B(p,45,34,46,40,41,44);B(p,35,48,28,43,24,36);B(p,21,43,17,46,12,42);B(p,8,39,9,34,11,30);B(p,7,29,4,25,6,20);B(p,8,16,11,16,13,16);B(p,9,12,3,8,5,4);p.CloseFigure();Paint(g,p,sh,hi,a,hi);}using(var q=P(b,2.2f)){g.DrawBezier(q,9,8,10,20,15,31,21,35);g.DrawBezier(q,31,18,37,20,39,25,36,30);}Hi(g,hi,13,10,6,4);Hi(g,hi,31,20,6,5);Hi(g,hi,35,36,3.5f,3.5f);}
 static void Flame(Graphics g,Color sh,Color a,Color b,Color hi){using(var p=new GraphicsPath()){p.StartFigure();p.AddBezier(5,4,18,8,34,16,43,24);B(p,47,29,41,34,34,32);B(p,41,38,39,45,32,43);B(p,28,41,25,36,22,33);B(p,20,41,15,45,11,41);B(p,8,38,9,33,10,29);B(p,7,21,5,13,5,4);p.CloseFigure();Paint(g,p,sh,b,a,hi);}using(var q=P(hi,2.5f)){g.DrawBezier(q,8,8,13,13,17,18,20,25);g.DrawBezier(q,16,28,22,25,28,27,34,31);g.DrawBezier(q,13,35,18,33,23,37,28,41);}using(var q=P(a,1.8f))g.DrawBezier(q,13,14,20,13,25,17,28,23);Hi(g,hi,14,13,3,3);Hi(g,hi,28,34,4,4);}
 static void Leaf(Graphics g,Color sh,Color a,Color b,Color hi,Color core){using(var p=new GraphicsPath()){p.StartFigure();p.AddBezier(5,4,20,5,37,12,42,24);B(p,46,35,38,42,27,41);B(p,32,44,38,46,35,48);B(p,31,50,27,44,23,41);B(p,13,42,7,35,6,25);B(p,4,16,3,7,5,4);p.CloseFigure();Paint(g,p,sh,hi,b,hi);}using(var q=P(core,2.8f))g.DrawBezier(q,7,7,16,19,25,31,35,44);using(var q=P(a,2f)){g.DrawBezier(q,14,17,20,16,24,18,27,22);g.DrawBezier(q,20,26,27,24,32,27,36,31);g.DrawBezier(q,15,30,20,32,24,35,27,38);}Hi(g,hi,14,12,4,4);Hi(g,hi,30,20,5,4);}
 static void CreamStar(Graphics g,Color sh,Color a,Color b,Color hi){using(var p=new GraphicsPath()){p.AddPolygon(new[]{new PointF(5,4),new PointF(20,14),new PointF(32,9),new PointF(31,22),new PointF(43,29),new PointF(34,35),new PointF(34,44),new PointF(25,40),new PointF(19,47),new PointF(15,38),new PointF(5,40),new PointF(9,29),new PointF(2,22),new PointF(13,18)});p.CloseFigure();Paint(g,p,sh,hi,b,hi);}using(var q=P(a,2.2f)){g.DrawLine(q,8,8,22,17);g.DrawLine(q,22,17,30,13);g.DrawLine(q,12,29,20,36);g.DrawLine(q,20,36,27,42);}Hi(g,hi,14,12,5,4);Hi(g,hi,31,25,4,3);}
 static void Bolt(Graphics g,Color sh,Color a,Color b,Color hi){using(var p=new GraphicsPath()){p.AddPolygon(new[]{new PointF(6,4),new PointF(38,19),new PointF(29,25),new PointF(42,34),new PointF(25,46),new PointF(27,35),new PointF(9,30),new PointF(18,22)});p.CloseFigure();Paint(g,p,sh,hi,b,hi);}using(var q=P(a,2.5f)){g.DrawLine(q,11,9,29,19);g.DrawLine(q,29,19,22,25);g.DrawLine(q,22,25,35,33);g.DrawLine(q,35,33,28,39);}Hi(g,hi,13,11,5,4);}
 static void Hand(Graphics g,Color sh,Color a,Color b,Color hi){using(var p=new GraphicsPath()){p.StartFigure();p.AddBezier(20,3,17,3,16,6,16,11);B(p,16,15,16,19,16,23);p.AddLine(16,23,12,19);B(p,9,16,6,18,7,22);p.AddLine(7,22,15,36);B(p,18,43,25,46,32,42);B(p,39,38,41,30,38,23);B(p,37,19,33,19,32,23);B(p,32,17,28,16,26,20);p.AddLine(26,20,26,10);B(p,26,5,23,3,20,3);p.CloseFigure();Paint(g,p,sh,hi,a,hi);}using(var q=P(b,2.1f)){g.DrawBezier(q,17,25,22,23,27,24,31,29);g.DrawBezier(q,18,35,23,39,29,39,34,35);}Hi(g,hi,19,7,3.5f,8);}
 static void Swirl(Graphics g,Color sh,Color a,Color b,Color hi){using(var p=new GraphicsPath()){p.StartFigure();p.AddBezier(6,3,13,2,23,7,22,15);B(p,32,11,40,15,39,24);B(p,47,25,48,34,40,38);B(p,42,45,33,48,27,42);B(p,20,48,10,44,11,35);B(p,3,33,4,24,11,21);B(p,5,17,2,8,6,3);p.CloseFigure();Paint(g,p,sh,hi,b,hi);}using(var q=P(a,2.7f)){g.DrawBezier(q,9,18,17,23,29,22,37,18);g.DrawBezier(q,10,32,20,37,32,36,40,31);}using(var q=P(b,2.1f))g.DrawBezier(q,14,41,20,44,26,44,30,41);}
}
